module top_module(
    input clkA,
    input clkB,
    input in,
    output out,
    output busy
    );reg toggleA = 1'b0;;
    always @(posedge clkA) toggleA <= toggleA ^ in;


    reg [3:0] syncA = 4'b0;
    always @(posedge clkB) syncA <= {syncA[2:0], toggleA};

    reg [2:0] syncB = 2'b0;
    always @(posedge clkA) syncB <= {syncB[1:0], syncA[3]};

    assign out = (syncA[3] ^ syncA[2]);
    assign busy = (toggleA ^ syncB[2]);

endmodule

