module fsm (
    input wire IN,
    input wire CLK,
    input wire RST,
    output reg MATCH
);

    // State encoding
    typedef enum reg [2:0] {
        S0 = 3'b000,  // Initial state
        S1 = 3'b001,  // After detecting first '1'
        S2 = 3'b010,  // After detecting '10'
        S3 = 3'b011,  // After detecting '100'
        S4 = 3'b100,  // After detecting '1001'
        S5 = 3'b101   // After detecting '10011'
    } state_t;

    state_t state, next_state;

    // State transition logic
    always @(posedge CLK or posedge RST) begin
        if (RST)
            state <= S0;
        else
            state <= next_state;
    end

    // Next state logic and output logic
    always @(*) begin
        next_state = state;
        MATCH = 0;
        case (state)
            S0: begin
                if (IN)
                    next_state = S1;
            end
            S1: begin
                if (!IN)
                    next_state = S2;
                else
                    next_state = S1;
            end
            S2: begin
                if (!IN)
                    next_state = S3;
                else if (IN)
                    next_state = S1;
            end
            S3: begin
                if (IN)
                    next_state = S4;
                else
                    next_state = S0;
            end
            S4: begin
                if (IN) begin
                    next_state = S5;
                    MATCH = 1;
                end else
                    next_state = S2;
            end
            S5: begin
                if (!IN)
                    next_state = S2;
                else
                    next_state = S1;
            end
            default: next_state = S0;
        endcase
    end

endmodule

