module top_module(
  input clock,
  input reset,
  input [15:0] left_data,
  input [15:0] right_data,
  output reg mclk,    // Changed to reg
  output reg lrck,    // Changed to reg
  output reg sclk,    // Changed to reg
  output reg sdin     // Changed to reg
);reg [5:0] mclk_counter; // Counter for MCLK
  reg [4:0] sclk_counter; // Counter for SCLK
  reg lrck_state; // State of LRCK
  reg [15:0] data_counter; // Counter for SDIN
  reg [15:0] data_out; // Data output for SDIN

  // Reset outputs on rising edge of clock if reset is high
  always @(posedge clock) begin
    if (reset) begin
      mclk_counter <= 0;
      sclk_counter <= 0;
      lrck_state <= 0;
      data_counter <= 0;
      data_out <= 0;
      mclk <= 0;
      lrck <= 0;
      sclk <= 0;
      sdin <= 0;
    end
  end

  // Generate MCLK
  always @(posedge clock) begin
    if (!reset) begin
      mclk_counter <= mclk_counter + 1;
      if (mclk_counter == 31) begin
        mclk_counter <= 0;
        mclk <= ~mclk;
      end
    end
  end

  // Generate LRCK
  always @(posedge clock) begin
    if (!reset) begin
      sclk_counter <= sclk_counter + 1;
      if (sclk_counter == 7) begin
        sclk_counter <= 0;
        lrck_state <= ~lrck_state;
      end
      lrck <= lrck_state;
    end
  end

  // Generate SCLK and SDIN
  always @(posedge clock) begin
    if (!reset) begin
      sclk_counter <= sclk_counter + 1;
      if (sclk_counter == 15) begin
        sclk_counter <= 0;
        sclk <= ~sclk;
        if (lrck_state) begin // Left channel
          data_out <= left_data;
        end
        else begin // Right channel
          data_out <= right_data;
        end
        data_counter <= data_counter + 1;
        if (data_counter == 15) begin
          data_counter <= 0;
        end
        sdin <= data_out[15];
        data_out <= {data_out[14:0], 1'b0};
      end
    end
  end

endmodule

