module top_module(
  input vin,
  input clk,
  input reset,
  input freq_min,
  input freq_max,
  output reg vco_out
);reg [31:0] counter;
  reg [31:0] phase_accumulator;
  reg [31:0] phase_increment;
  reg [31:0] frequency;
  reg [31:0] voltage_scaled;
  reg [31:0] voltage_range;
  reg [31:0] freq_range;
  reg [31:0] freq_scaled;
  reg [31:0] freq_offset;

  always @ (posedge clk or posedge reset) begin
    if (reset) begin
      counter <= 0;
      phase_accumulator <= 0;
      phase_increment <= 0;
      frequency <= 0;
      voltage_scaled <= 0;
      voltage_range <= 0;
      freq_range <= 0;
      freq_scaled <= 0;
      freq_offset <= 0;
      vco_out <= 0;
    end else begin
      counter <= counter + 1;
      phase_accumulator <= phase_accumulator + phase_increment;
      if (phase_accumulator >= 2**32) begin
        phase_accumulator <= phase_accumulator - 2**32;
      end
      if (counter >= frequency) begin
        counter <= 0;
        vco_out <= ~vco_out;
      end
    end
  end

  always @ (vin) begin
    voltage_scaled <= (vin * 2**31) / 5;
    voltage_range <= freq_max - freq_min;
    freq_range <= (voltage_scaled * voltage_range) / 2**31;
    freq_scaled <= freq_min + freq_range;
    freq_offset <= freq_scaled - clk;
    phase_increment <= (freq_offset * 2**32) / clk;
    frequency <= clk / freq_offset;
  end

endmodule

