module top_module(
    input CLOCK_50,
    input [9:0] SW,
    input [3:0] KEY,
    output reg [9:0] LEDR
);reg [9:0] led_delay;
reg [4:0] led_index;

parameter DELAY = 20;

always @(posedge CLOCK_50) begin
    if (SW == 12) begin
        LEDR <= 10'b0000000000;
    end else begin
        case (led_index)
            0: LEDR <= 10'b0000000001;
            1: LEDR <= 10'b0000000010;
            2: LEDR <= 10'b0000000100;
            3: LEDR <= 10'b0000001000;
            4: LEDR <= 10'b0000010000;
            5: LEDR <= 10'b0000100000;
            6: LEDR <= 10'b0001000000;
            7: LEDR <= 10'b0010000000;
            8: LEDR <= 10'b0100000000;
            9: LEDR <= 10'b1000000000;
            default: LEDR <= 10'b0000000000;
        endcase
    end
end

always @(posedge CLOCK_50) begin
    if (SW[9] == 1) begin
        led_delay <= DELAY;
        led_index <= 0;
    end else if (SW[8] == 1) begin
        if (led_delay == 0) begin
            LEDR[0] <= 1;
            led_delay <= DELAY;
        end else begin
            led_delay <= led_delay - 1;
        end
    end else if (SW[8] == 0) begin
        if (led_delay == 0) begin
            LEDR[0] <= 0;
            led_delay <= DELAY;
        end else begin
            led_delay <= led_delay - 1;
        end
    end
end

always @(posedge CLOCK_50) begin
    if (KEY[0] == 1) begin
        led_delay <= DELAY;
        led_index <= 1;
    end else if (KEY[1] == 1) begin
        led_delay <= DELAY;
        led_index <= 2;
    end else if (KEY[2] == 1) begin
        led_delay <= DELAY;
        led_index <= 3;
    end else if (KEY[3] == 1) begin
        led_delay <= DELAY;
        led_index <= 4;
    end else if (led_delay > 0) begin
        led_delay <= led_delay - 1;
    end else if (led_index > 0) begin
        led_index <= led_index + 1;
    end
end

endmodule

