module state_machine (
        input clk,
        input reset,
        input x,
        output reg z);parameter S0=0, S1=1, S2=2, S3=3, S4=4;
	reg [2:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= S0;
		else 
			state <= next;


	always_comb begin
		case(state)
			S0: next = x ? S2 : S1;
			S1: next = x ? S4 : S3;
			S2: next = x ? S3 : S1;
			S3: next = x ? S4 : S0;
			S4: next = x ? S0 : S2;
			default: next = 'x;
		endcase
	end

	assign z = (state == S2 || state == S4);

endmodule

