	case(ALUop)
		3'b010:	result	=	inputA	+	inputB;
		3'b110:	result	=	inputA	-	inputB;
		3'b001:	result	=	inputA	|	inputB;
		3'b000:	result	=	inputA	&	inputB;
		3'b111:	
		begin
			if(inputA < inputB)
				result	=	1;
			else
				result	=	0;
		end
	endcase

	if (inputA == inputB)
			zero = 1;
	else
			zero = 0;
end 
endmodule

