    output Y_N;
    input A;
    input B;
    input C;
    input D_N;

    // Local signals
    wire not_D_N;
    wire nor_ABCD;
    wire buf_Y;

    //  Name  Output      Other arguments
    not not0 (not_D_N, D_N);
    nor nor0 (nor_ABCD, A, B, C, not_D_N);
    buf buf0 (buf_Y, nor_ABCD);
    assign Y = buf_Y;
    assign Y_N = ~buf_Y;

