module top_module( 
    input [3:0] a, b, // 4-bit inputs for multiplier
    input [255:0] in, // 256-bit input for comparator
    input clk, // Added clk input for the comparator
    output reg [7:0] out );// 8-bit output for final result

    reg [7:0] product; // 8-bit product output from multiplier
    reg [7:0] pattern = 8'b10101010; // 8-bit pattern to detect

    // Multiplier module
    // Uses only AND and XOR gates to produce an 8-bit output from two 4-bit inputs
    // Output is stored in 'product' register
    always @* begin
        product = {a[0] & b[0], a[0] & b[1], a[1] & b[0], a[1] & b[1], a[2] & b[0], a[2] & b[1], a[3] & b[0], a[3] & b[1]} ^ 8'b00000000;
    end

    // Comparator module
    // Uses a shift register to compare the 256-bit input vector with the 8-bit pattern
    // Output is stored in 'out' register
    reg [7:0] shift_reg;
    integer i;
    always @(posedge clk) begin
        shift_reg <= {shift_reg[6:0], in[255]};
        if (shift_reg == pattern) begin
            out <= 8'b00000001;
        end else begin
            out <= 8'b00000000;
        end
    end

endmodule

module top_module(
  input clk,
  input reset,
  input [3:0] a,
  input [3:0] b,
  output reg [3:0] sum,
  output reg carry,
  output reg [2:0] count,
  output reg [3:0] so
);reg [3:0] a_reg, b_reg;
  reg [1:0] sum_reg;
  reg carry_reg;

  always @(posedge clk) begin
    if (reset) begin
      a_reg <= 4'b0;
      b_reg <= 4'b0;
      sum_reg <= 2'b0;
      carry_reg <= 1'b0;
      sum <= 4'b0;
      carry <= 1'b0;
      count <= 3'b0;
      so <= 4'b0;
    end else begin
      a_reg <= {a_reg[2:0], a};
      b_reg <= {b_reg[2:0], b};
      sum_reg <= {sum_reg[0], a_reg[0] ^ b_reg[0]};
      carry_reg <= a_reg[0] & b_reg[0];
      sum <= {sum_reg[1], sum_reg[0], a_reg[1:0] ^ b_reg[1:0]};
      carry <= carry_reg | (sum_reg[1] & carry_reg);
      count <= count + 1;
      so <= {sum_reg, a_reg[2]};
    end
  end

endmodule

