description:
Design a pipeline register that synchronizes control and data signals from a previous stage of a processor to a subsequent stage. The module captures and holds values for various inputs, including data and control signals, on the rising edge of the clock, while also implementing a synchronous reset feature. When reset is not active, it passes through input signals such as register write enable, memory operations, ALU control signals, and data lines, thereby facilitating smooth handoff and maintaining the integrity of the data flow within a pipelined architecture.
module top_module(dwreg,dm2reg,dwmem,daluc,daluimm,da,db,dimm,dsa,drn,dshift,djal,dpc4,clock,resetn,
					ewreg,em2reg,ewmem,ealuc,ealuimm,ea,eb,esa, eimm,ern0,eshift,ejal,epc4);

code:
module top_module(dwreg,dm2reg,dwmem,daluc,daluimm,da,db,dimm,dsa,drn,dshift,djal,dpc4,clock,resetn,
					ewreg,em2reg,ewmem,ealuc,ealuimm,ea,eb,esa, eimm,ern0,eshift,ejal,epc4);input [31:0] dimm, dpc4, da, db, dsa;
		input [3:0] daluc;
		input [4:0] drn;
		input dwreg, dm2reg, dwmem, daluimm, dshift, djal, clock, resetn;

		output reg[31:0] ea, eb, eimm, epc4,esa;
		output reg[4:0] ern0;
		output reg[3:0] ealuc;
		output reg ewreg,em2reg,ewmem,ealuimm,eshift,ejal;

		always @(posedge clock)
	begin
		if(~resetn)
		begin
			ewreg <= 0;
			em2reg <= 0;
			ewmem <= 0;
			ealuimm <= 0;
			eshift <= 0;
			ejal <= 0;
			ea <= 0;
			eb <= 0;
			eimm <= 0;
			epc4 <= 0;
			ern0 <= 0;
			ealuc <= 0;
			esa <= 0;
		end
		else begin
			ewreg <= dwreg;
			em2reg <= dm2reg;
			ewmem <= dwmem;
			ealuimm <= daluimm;
			eshift <= dshift;
			ejal <= djal;
			ea <= da;
			eb <= db;
			eimm <= dimm;
			epc4 <= dpc4;
			ern0 <= drn;
			ealuc <= daluc;
			esa <= dsa;
		end
	end

endmodule

module decoder5to32(
	input 	clk,
	input 	rst,
	input 	enable,
	input 	[4:0] input_data,
	output reg [31:0] output_data
);

always @(posedge clk or posedge rst)
begin
	if (rst)
		output_data <= 32'b0;
	else if (enable)
		output_data <= 1 << input_data;
	else
		output_data <= 32'b0;
end

endmodule

